'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
// MON6: related extensions first in More free viewers, Marketplace pages instead of installs, PayPal only when set.
// support.js is generated by factory/sprint/monetize.py from funding.json and the live product list.
const support = require('../src/support.js');

const SELF = 'zovo.xmind-mind-map-viewer';

test('More free viewers starts with 3 to 5 related extensions, without this one', () => {
  const rel = support.relatedProducts(SELF);
  assert.ok(rel.length >= 3 && rel.length <= 5, String(rel.length));
  assert.ok(rel.every((p) => p.id !== SELF));
  assert.deepEqual(rel.map((p) => p.id), ["zovo.zovo-graphviz-preview", "zovo.mermaid-viewer", "zovo.pdf-viewer-dark", "zovo.docx-viewer-vscode", "zovo.pptx-slide-viewer"]);
  const items = support.pickItems(SELF, () => false);
  assert.equal(items[0].label, 'Related to this extension');
  assert.deepEqual(items.slice(1, 1 + rel.length).map((i) => i.product.id), rel.map((p) => p.id));
  const ids = items.filter((i) => i.product).map((i) => i.product.id);
  assert.equal(new Set(ids).size, ids.length);
});

test('the picker links the GitHub profile, the publisher page and only funding links that are set', () => {
  const items = support.pickItems(SELF, () => false);
  const links = items.filter((i) => i.link).map((i) => i.link);
  assert.ok(links.includes('https://github.com/theluckystrike'));
  assert.ok(links.includes('https://marketplace.visualstudio.com/publishers/zovo'));
  assert.ok(links.every((u) => /^https:\/\//.test(u)));
  assert.equal(links.some((u) => /paypal/i.test(u)), support.paypalUrl() !== '');
});

test('the footer shows PayPal only when funding.json has it', () => {
  const html = support.footerHtml('x', true, '');
  assert.equal(/>PayPal</.test(html), support.paypalUrl() !== '');
  assert.match(html, /More free viewers/);
  assert.equal(support.footerHtml('x', false, ''), '');
});

test('picking an extension opens its Marketplace page and never installs it', async () => {
  const ran = [];
  const opened = [];
  const cmds = {};
  let pickFn = async () => undefined;
  const vscode = {
    commands: { registerCommand: (id, fn) => { cmds[id] = fn; return { dispose() {} }; }, executeCommand: async (...a) => { ran.push(a); } },
    window: { showQuickPick: async (items) => pickFn(items), showInformationMessage: () => {} },
    env: { openExternal: async (u) => { opened.push(String(u)); return true; } },
    Uri: { parse: (u) => u },
    extensions: { getExtension: () => undefined },
    workspace: { getConfiguration: () => ({ get: (k, d) => d }) },
  };
  const s = support.registerSupport({ vscode, context: { subscriptions: [] }, prefix: 'x', selfId: SELF });
  const rel = support.relatedProducts(SELF);
  const firstLive = rel.find((p) => p.live);
  if (firstLive) {
    pickFn = async (items) => items.find((i) => i.product && i.product.id === firstLive.id);
    await s.moreViewers();
    assert.deepEqual(ran, [['extension.open', firstLive.id]]);
  }
  pickFn = async (items) => items.find((i) => i.link === 'https://github.com/theluckystrike');
  await s.moreViewers();
  assert.ok(opened.includes('https://github.com/theluckystrike'));
  assert.equal(ran.filter((a) => a[0] === 'workbench.extensions.installExtension').length, 0);
});
